import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/foundation.dart' show kDebugMode;
import 'package:flutter/services.dart' show AssetBundle, rootBundle;

import 'persona_seed.dart';

export 'persona_seed.dart';

/// Asset holding the four test personas (generated by tooling/persona_seed).
const String kPersonasAsset = 'assets/seed/personas.json';

/// Firestore caps a batch at 500 operations. Stay safely below it.
const int kSeedBatchLimit = 400;

/// Collections that hold seeded documents. Each one is tagged `is_demo: true`.
const List<String> kDemoCollections = [
  'clothing_items',
  'outfit_history',
  'events',
  'audit_events',
];

class DemoSeedResult {
  DemoSeedResult({
    required this.personaId,
    required this.itemsCreated,
    required this.outfitsCreated,
    required this.eventsCreated,
    required this.replacedDocs,
  });

  final String personaId;
  final int itemsCreated;
  final int outfitsCreated;
  final int eventsCreated;
  final int replacedDocs;
}

/// Seeds one of the four test personas into an existing signed-in account.
///
/// Gated on `kDebugMode` or `--dart-define=DLS_DEMO_MODE=true`. A release
/// build must never write synthetic wardrobe data into a real account.
/// Persona data holds derived attributes only; no training photos or product
/// names are bundled. Images are CC0 assets under `assets/seed/images/`.
class DemoDataService {
  DemoDataService({AssetBundle? bundle}) : _bundle = bundle ?? rootBundle;

  final AssetBundle _bundle;

  FirebaseFirestore get _firestore => FirebaseFirestore.instance;

  /// Gated on `kDebugMode` or `--dart-define=DLS_DEMO_MODE=true`, matching
  /// `MockWardrobeSeeder`.
  static const bool demoEnvFlag = bool.fromEnvironment('DLS_DEMO_MODE');
  static bool get isDemoEnabled => kDebugMode || demoEnvFlag;

  Future<List<DemoPersona>> loadPersonas() async {
    final raw = await _bundle.loadString(kPersonasAsset);
    return parsePersonas(raw);
  }

  /// Replaces any existing test data for [userId] with the wardrobe, outfits
  /// and events of the persona [personaId].
  Future<DemoSeedResult> seedForUser(
    String userId, {
    required String personaId,
  }) async {
    if (!isDemoEnabled) {
      throw StateError('Test persona seeding is disabled in release builds.');
    }

    final personas = await loadPersonas();
    DemoPersona? persona;
    for (final candidate in personas) {
      if (candidate.id == personaId) {
        persona = candidate;
        break;
      }
    }
    if (persona == null) {
      throw ArgumentError.value(personaId, 'personaId', 'Unknown persona');
    }

    final now = DateTime.now();
    final replaced = await _deleteExistingDemoDocs(userId);
    final plan = buildPersonaWrites(
      persona: persona,
      userId: userId,
      now: now,
      newId: () => _firestore.collection('clothing_items').doc().id,
    );
    await _writeAll(plan.writes);

    return DemoSeedResult(
      personaId: persona.id,
      itemsCreated: plan.itemCount,
      outfitsCreated: plan.outfitCount,
      eventsCreated: plan.eventCount,
      replacedDocs: replaced,
    );
  }

  /// Deletes every `is_demo` document owned by [userId]. Both the camelCase and
  /// snake_case owner fields are matched, because older builds wrote either.
  Future<int> _deleteExistingDemoDocs(String userId) async {
    final refs = <DocumentReference<Map<String, dynamic>>>{};
    for (final collection in kDemoCollections) {
      for (final ownerField in const ['userId', 'user_id']) {
        final snapshot = await _firestore
            .collection(collection)
            .where(ownerField, isEqualTo: userId)
            .where('is_demo', isEqualTo: true)
            .get();
        refs.addAll(snapshot.docs.map((doc) => doc.reference));
      }
    }

    final list = refs.toList(growable: false);
    for (var start = 0; start < list.length; start += kSeedBatchLimit) {
      final batch = _firestore.batch();
      for (final ref in list.skip(start).take(kSeedBatchLimit)) {
        batch.delete(ref);
      }
      await batch.commit();
    }
    return list.length;
  }

  Future<void> _writeAll(List<PlannedWrite> writes) async {
    for (var start = 0; start < writes.length; start += kSeedBatchLimit) {
      final batch = _firestore.batch();
      for (final write in writes.skip(start).take(kSeedBatchLimit)) {
        batch.set(
          _firestore.collection(write.collection).doc(write.id),
          write.data,
          SetOptions(merge: write.merge),
        );
      }
      await batch.commit();
    }
  }
}
